package honcho

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"time"
	"unicode/utf8"
)

// peerIDPattern validates peer ID format
var peerIDPattern = regexp.MustCompile(`^[a-zA-Z0-9_-]+$`)

// Peer represents a Honcho peer
type Peer struct {
	ID string `json:"id"`
	// UID is the immutable identifier Honcho assigns to this peer. ID is the name the client chose, UID is generated by the server
	UID           string          `json:"uid"`
	WorkspaceID   string          `json:"workspace_id"`
	CreatedAt     time.Time       `json:"created_at"`
	Metadata      json.RawMessage `json:"metadata,omitempty"`
	Configuration PeerConfig      `json:"configuration,omitzero"`
}

// PeerConfig represents the workspace-level configuration for a peer
type PeerConfig struct {
	// ObserveMe indicates whether Honcho will use reasoning to form a representation of this peer
	ObserveMe *bool `json:"observe_me"`
	// ObserveOthers indicates whether this peer should form a session-level theory-of-mind representation of other peers
	ObserveOthers *bool `json:"observe_others"`
}

// PeerCreate represents the request body for creating/getting a peer
type PeerCreate struct {
	ID            string          `json:"id"`
	Metadata      json.RawMessage `json:"metadata,omitempty"`
	Configuration PeerConfig      `json:"configuration,omitzero"`
}

// Validate checks that mandatory fields are valid
func (req PeerCreate) Validate() error {
	if req.ID == "" {
		return errors.New("id is required")
	}
	if len(req.ID) > 512 {
		return errors.New("id must be 512 characters or less")
	}
	if !peerIDPattern.MatchString(req.ID) {
		return errors.New("id must contain only letters, numbers, underscores, or hyphens")
	}
	return nil
}

// PeerKind represents the kind of peers GetAllPeers lists
type PeerKind string

const (
	// PeerKindScope lists the scope peers only
	PeerKindScope PeerKind = "scope"
	// PeerKindAll lists every peer
	PeerKindAll PeerKind = "all"
)

// PeerGet represents the request body for getting peers with filters
// Use nil for no filters
type PeerGet struct {
	Filters map[string]any `json:"filters,omitempty"`
	// Kind is the kind of peers to list (default: empty, regular peers only). The server answers
	// any value other than PeerKindScope and PeerKindAll with a 422
	Kind PeerKind `json:"kind,omitempty"`
}

// PagePeer represents a paginated response of peers
type PagePeer struct {
	Items []Peer `json:"items"`
	Total int    `json:"total"`
	Page  int    `json:"page"`
	Size  int    `json:"size"`
	Pages int    `json:"pages"`
}

// PeerUpdate represents the request body for updating a peer
type PeerUpdate struct {
	Metadata      json.RawMessage `json:"metadata,omitempty"`
	Configuration PeerConfig      `json:"configuration,omitzero"`
}

// PeerRepresentationGet represents the request body for getting a peer's representation
type PeerRepresentationGet struct {
	// SessionID is optional session ID within which to scope the representation
	SessionID *string `json:"session_id,omitempty"`
	// Target is optional peer ID to get the representation for, from the perspective of this peer
	Target *string `json:"target,omitempty"`
	// SearchQuery is optional input to curate the representation around semantic search results
	SearchQuery *string `json:"search_query,omitempty"`
	// SearchTopK is only used if SearchQuery is provided. Number of semantic-search-retrieved conclusions to include (1-100)
	SearchTopK *int `json:"search_top_k,omitempty"`
	// SearchMaxDistance is only used if SearchQuery is provided. Maximum distance to search for semantically relevant conclusions (0-1)
	SearchMaxDistance *float64 `json:"search_max_distance,omitempty"`
	// IncludeMostFrequent is only used if SearchQuery is provided. Whether to include the most frequent conclusions
	IncludeMostFrequent *bool `json:"include_most_frequent"`
	// MaxConclusions is only used if SearchQuery is provided. Maximum number of conclusions to include (1-100, default: 25)
	MaxConclusions *int `json:"max_conclusions,omitempty"`
}

// RepresentationResponse represents the response for getting a peer's representation
type RepresentationResponse struct {
	Representation string `json:"representation"`
}

// PeerCardResponse represents the response for getting/setting a peer card
type PeerCardResponse struct {
	PeerCard []string `json:"peer_card,omitempty"`
}

// PeerCardSet represents the request body for setting a peer card
type PeerCardSet struct {
	// PeerCard replaces the whole peer card. An empty non-nil list clears the card.
	// A nil list is refused by Validate, as it would be sent as null, which upstream refuses.
	PeerCard []string `json:"peer_card"`
}

// Validate checks that mandatory fields are valid
func (req PeerCardSet) Validate() error {
	if req.PeerCard == nil {
		return errors.New("peer_card is required")
	}
	return nil
}

// PeerContext represents the response for getting peer context
type PeerContext struct {
	PeerID         string   `json:"peer_id"`
	TargetID       string   `json:"target_id"`
	Representation *string  `json:"representation,omitempty"`
	PeerCard       []string `json:"peer_card,omitempty"`
}

// Session represents a Honcho session
type Session struct {
	ID string `json:"id"`
	// UID is the immutable identifier Honcho assigns to this session. ID is the name the client chose, UID is generated by the server
	UID         string          `json:"uid"`
	IsActive    bool            `json:"is_active"`
	WorkspaceID string          `json:"workspace_id"`
	Metadata    json.RawMessage `json:"metadata,omitempty"`
	// Configuration is the session-level configuration, nil when the response holds none
	Configuration *SessionConfiguration `json:"configuration,omitempty"`
	CreatedAt     time.Time             `json:"created_at"`
	// Scopes is the names of the scopes the session is in. It is nil unless GetSessionsOptions.IncludeScopes
	// is set, and empty for a session in no scope
	Scopes []string `json:"scopes,omitempty"`
}

// GetAllPeersOptions represents optional parameters for GetAllPeers
type GetAllPeersOptions struct {
	Page int // Page is the page number (default: 1, minimum: 1)
	Size int // Size is the page size (default: 50, minimum: 1, maximum: 100)
	// Reverse is whether to reverse the order of results, newest peer first (default: false)
	Reverse bool `json:"reverse,omitempty"`
}

// GetSessionsForPeerOptions represents optional parameters for GetSessionsForPeer
type GetSessionsForPeerOptions struct {
	Page int // Page is the page number (default: 1, minimum: 1)
	Size int // Size is the page size (default: 50, minimum: 1, maximum: 100)
	// Reverse is whether to reverse the order of results, newest session first (default: false)
	Reverse bool `json:"reverse,omitempty"`
}

// GetPeerContextOptions represents optional parameters for GetPeerContext
type GetPeerContextOptions struct {
	// Target is optional target peer to get context for, from the observer's perspective
	Target *string
	// SearchQuery is optional query to curate the representation around semantic search results
	SearchQuery *string
	// SearchTopK is number of semantic-search-retrieved conclusions to include (1-100)
	SearchTopK *int
	// SearchMaxDistance is maximum distance for semantically relevant conclusions (0-1)
	SearchMaxDistance *float64
	// IncludeMostFrequent is whether to include the most frequent conclusions (default: true)
	IncludeMostFrequent *bool
	// MaxConclusions is maximum number of conclusions to include (1-100)
	MaxConclusions *int
}

// ReasoningLevel represents the level of reasoning for chat
type ReasoningLevel string

const (
	ReasoningLevelMinimal ReasoningLevel = "minimal"
	ReasoningLevelLow     ReasoningLevel = "low"
	ReasoningLevelMedium  ReasoningLevel = "medium"
	ReasoningLevelHigh    ReasoningLevel = "high"
	ReasoningLevelMax     ReasoningLevel = "max"
)

// DialecticOptions represents the request body for chatting with a peer's representation
type DialecticOptions struct {
	// SessionID is ID of the session to scope the representation to
	SessionID *string `json:"session_id,omitempty"`
	// Target is optional peer to get the representation for, from the perspective of this peer
	Target *string `json:"target,omitempty"`
	// Query is the dialectic API prompt (1-10000 characters)
	Query string `json:"query"`
	// Stream is whether to stream the response (default: false). ChatStream sets it and Chat refuses it
	Stream bool `json:"stream,omitempty"`
	// ReasoningLevel is the level of reasoning to apply (default: low)
	ReasoningLevel ReasoningLevel `json:"reasoning_level,omitempty"`
}

// Validate checks that mandatory fields are valid
func (req DialecticOptions) Validate() error {
	if req.Query == "" {
		return errors.New("query is required")
	}
	if utf8.RuneCountInString(req.Query) > 10000 {
		return errors.New("query must be 10000 characters or less")
	}
	return nil
}

// DialecticResponse represents the response for chatting with a peer's representation or a whole workspace
type DialecticResponse struct {
	Content *string `json:"content"`
	// Evidence is what the answer was built from. Present only when include_evidence is true
	Evidence *Evidence `json:"evidence,omitempty"`
}

// Evidence represents what the dialectic agent read and did while answering. It is collated
// from the agent's own reads rather than reported by the model, so it is deterministic but
// over-reports: it lists what the agent accessed, which is not necessarily what the answer relied on
type Evidence struct {
	// Conclusions are the conclusions the agent read, whether prefetched or found via its tools
	Conclusions []EvidenceObservation `json:"conclusions"`
	// Messages are the messages the agent read via its search and grep tools, by ID and provenance
	// only. Fetch a message to read its content
	Messages []EvidenceMessageRef `json:"messages"`
	// ToolCalls are the tools the agent invoked, in order, with their arguments. Results are omitted
	// (they are reflected in Conclusions and Messages), and so are calls that failed, so this is a
	// record of successful invocations rather than a complete reasoning trace
	ToolCalls []EvidenceToolCall `json:"tool_calls"`
	// ReasoningTraceID is the ID of the stored reasoning trace for this call, when trace storage is enabled
	ReasoningTraceID *string `json:"reasoning_trace_id,omitempty"`
}

// EvidenceObservation represents a conclusion the dialectic agent read while answering
type EvidenceObservation struct {
	// ID is the conclusion (document) ID
	ID string `json:"id"`
	// Level is the conclusion level: explicit, deductive, inductive, or contradiction
	Level ConclusionLevel `json:"level"`
	// Content is the conclusion text (the derived conclusion, for non-explicit levels)
	Content string `json:"content"`
	// CreatedAt is when the conclusion was derived, from its source messages when known
	CreatedAt time.Time `json:"created_at"`
	// SessionID is the session the conclusion is scoped to, if any
	SessionID *string `json:"session_id,omitempty"`
	// ObserverID is the peer who made the conclusion
	ObserverID string `json:"observer_id"`
	// ObservedID is the peer the conclusion is about
	ObservedID string `json:"observed_id"`
	// SourceIDs are the IDs of the conclusions this one was derived from. Empty for explicit
	// conclusions, which derive from messages rather than from other conclusions
	SourceIDs []string `json:"source_ids"`
}

// EvidenceMessageRef represents a message the dialectic agent read while answering: its identity
// and provenance only, without its content. Fetch the message by ID when the text is needed
type EvidenceMessageRef struct {
	// ID is the message ID
	ID string `json:"id"`
	// SessionID is the session the message belongs to
	SessionID string `json:"session_id"`
	// PeerID is the peer who sent the message
	PeerID string `json:"peer_id"`
	// CreatedAt is when the message was sent
	CreatedAt time.Time `json:"created_at"`
}

// EvidenceToolCall represents a tool the dialectic agent invoked while answering
type EvidenceToolCall struct {
	// ToolName is the name of the tool
	ToolName string `json:"tool_name"`
	// ToolInput holds the arguments the agent passed to the tool, as a JSON object
	ToolInput json.RawMessage `json:"tool_input"`
}

// dialecticStreamFrame represents a frame of the event stream ChatStream and WorkspaceChatStream read
type dialecticStreamFrame struct {
	// Delta holds the next chunk of the answer, if the frame has one
	Delta struct {
		// Content is the text of the chunk
		Content string `json:"content"`
	} `json:"delta"`
	// Done is whether this is the final frame of a complete answer
	Done bool `json:"done"`
}

// decodeLine decodes a line of the event stream into the frame. A blank line, or
// a line that is not a data field, leaves the frame empty.
func (frame *dialecticStreamFrame) decodeLine(line []byte) (err error) {
	data, isData := bytes.CutPrefix(line, []byte("data:"))
	if data = bytes.TrimSpace(data); !isData || len(data) == 0 {
		return
	}
	// json.Unmarshal would take a null for an empty frame
	if data[0] != '{' {
		err = errors.New("failed to decode stream frame: not a JSON object")
		return
	}
	if err = json.Unmarshal(data, frame); err != nil {
		err = fmt.Errorf("failed to decode stream frame: %w", err)
	}
	return
}
